#include <iostream>
#include <vector>
#include <algorithm>
struct Item { int key; int id; };
int main() {
    std::vector<Item> a = {{1,0},{2,1},{1,2},{3,3},{2,4},{1,5}};
    auto byKey = [](const Item& x, const Item& y){ return x.key < y.key; };
    std::stable_sort(a.begin(), a.end(), byKey);
    for (auto& it : a) std::cout << it.key << ':' << it.id << ' ';
    std::cout << '\n';
}
